    local rule_metatable = {
        __tostring = function(self)
            local result = {}
            table.insert(result, tostring(self.lhs))
            table.insert(result, "→")
            if self.rhs:len() == 0 then
                table.insert(result, "λ")
            else
                table.insert(result, tostring(self.rhs))
            end
            return table.concat(result)
        end
    }

    local grammar_metatable = {
        __tostring = function(self)
            local result = {}
            table.insert(result, tostring(self.variables))
            table.insert(result, tostring(self.symbols))
            table.insert(result, tostring(self.rules))
            table.insert(result, tostring(self.start_variable))
