        end
    }

    function automata.make_grammar()
        local grammar = {
            variables = util.make_ordered_set(),
            symbols = util.make_ordered_set(),
            rules = util.make_ordered_set(),
            start_variable = nil,
        }

        local function add_missing_variables_and_symbols(self, sequence)
            for i=1,sequence:len() do
                local char = sequence:get_char(i)
                if not self.variables[char] and not self.symbols[char] then
                    -- TODO use unicode library to check
                    if char ~= string.lower(char) then
                        self.variables[char] = true
                        if char == "S" and not self.start_variable then
                            self.start_variable = char
                        end
                    else
                        self.symbols[char] = true
                    end
                end
            end
        end

        function grammar:add_variable(variable)
            self.variables[variable] = true
        end

