        end

        function grammar:add_rule(lhs, rhs)
            assert(lhs)
            assert(rhs)
            if type(lhs) == "string" then
                lhs = automata.tokenise_word(lhs)
            end
            assert(automata.is_token_sequence(lhs))
            add_missing_variables_and_symbols(grammar, lhs)
            if type(rhs) == "string" then
                rhs = automata.tokenise_word(rhs)
            end
            assert(automata.is_token_sequence(rhs), type(rhs))
            add_missing_variables_and_symbols(grammar, rhs)
            local rule = {lhs=lhs, rhs=rhs}
            setmetatable(rule, rule_metatable)
            self.rules[rule] = true
